// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] calldata _tos, uint v, uint _decimals) public {
        vm.assume(_tos.length > 0);
        vm.assume(caddress != address(0));
        vm.assume(caddress != address(this));
        vm.assume(caddress != address(c));
        for (uint i = 0; i < _tos.length; i++) {
            vm.assume(_tos[i] != address(0));
            vm.assume(_tos[i] != caddress);
        }
        (bool success, bytes memory ret) = address(c).call(abi.encodeWithSignature("transfer(address,address,address[],uint256,uint256)", from, caddress, _tos, v, _decimals));
        assertTrue(success && (ret.length >= 32) && (abi.decode(ret, (bool)) == true));
    }
}
